xyz_t spolar2world(VecSph* sph) {
    xyz_t v;
    f32 sinPitch;
    f32 cosPitch = cos_s(sph->pitch);
    f32 sinYaw;
    f32 cosYaw = cos_s(sph->yaw);

    sinPitch = sin_s(sph->pitch);
    sinYaw = sin_s(sph->yaw);

    v.x = sph->r * sinPitch * sinYaw;
    v.y = sph->r * cosPitch;
    v.z = sph->r * sinPitch * cosYaw;

    return v;
}

