s16 MultiplyQ8(s16 num1, s16 num2)
{
    s32 product;
    s32 rounded;

    product = num1 * num2;
    rounded = product;
    if (rounded < 0)
    {
        rounded += 0xFF;
    }
    product = rounded >> 8;
    return product;
}

