        case B_BUTTON:
            sector->buttonConfig.attack = 1;
            break;
        case R_BUTTON:
            sector->buttonConfig.trick = 1;
            break;
    }

    switch (save->buttonConfig.attack) {
        case A_BUTTON:
            sector->buttonConfig.jump = 2;
            break;
        case B_BUTTON:
            sector->buttonConfig.attack = 2;
            break;
        case R_BUTTON:
            sector->buttonConfig.trick = 2;
